SELECT  FROM ai_competition

    audit_status = #{status}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE ai_competition
SET name = #{name}, source_url = #{sourceUrl}, normalized_url = #{normalizedUrl},
    summary = #{summary}, organizer = #{organizer},
    start_time = #{startTime}, end_time = #{endTime}
WHERE id = #{id}

UPDATE ai_competition
SET audit_status = 'REJECTED', reviewer_id = #{reviewerId}, reject_reason = #{reason}
WHERE id = #{id} AND audit_status = 'PENDING'
